import Foundation

/// The synthetic image files in `Tests/Fixtures/` (generated by `Tests/Fixtures/generate.swift`; no client photos).
/// SwiftPM resources are not used in v1, so the folder is located relative to this source file.
public enum TestFixtureFiles {
    public static let directory: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()      // HMBFixtures
        .deletingLastPathComponent()      // Sources
        .deletingLastPathComponent()      // package root
        .appending(path: "Tests/Fixtures", directoryHint: .isDirectory)

    /// sRGB JPEG, 640×427, smooth warm gradient with soft shapes.
    public static var gradientSRGB: URL { directory.appending(path: "gradient-srgb.jpg") }
    /// Display P3 JPEG (embedded ICC profile), 640×427, saturated colour ramps.
    public static var rampsP3: URL { directory.appending(path: "ramps-p3.jpg") }
    /// PNG, 512×512, hard-edged high-chroma checker and fine lines (texture and chroma stress).
    public static var patternPNG: URL { directory.appending(path: "pattern.png") }
    /// JPEG stored as 427×640 landscape pixels with EXIF orientation 6 (displays portrait).
    public static var orientation6: URL { directory.appending(path: "orientation-6.jpg") }
    /// CMYK JPEG (Adobe APP14), 320×213.
    public static var cmyk: URL { directory.appending(path: "cmyk.jpg") }
    /// Arithmetic-coded JPEG (SOF9), 320×213.
    public static var arithmetic: URL { directory.appending(path: "arithmetic.jpg") }
    /// JPEG with a COM marker "holdmybyte" (a previous holdmybyte output), 320×213.
    public static var holdMyByteOutput: URL { directory.appending(path: "holdmybyte-output.jpg") }
    /// Large flat-ish image for the mosaic (2400×1600 JPEG, low quality to stay small).
    public static var mosaicSource: URL { directory.appending(path: "mosaic-2400x1600.jpg") }

    public static var all: [URL] {
        [gradientSRGB, rampsP3, patternPNG, orientation6, cmyk, arithmetic, holdMyByteOutput, mosaicSource]
    }
}
